package org.telegram.messenger; import java.util.*; public class SharedConfig { public static ArrayList<ProxyInfo> proxyList=new ArrayList<>(); public static ProxyInfo currentProxy; public static void loadProxyList(){} public static void saveProxyList(){} public static ProxyInfo addProxy(ProxyInfo p){ for(ProxyInfo q:proxyList){if(p.address.equals(q.address)&&p.port==q.port&&p.secret.equals(q.secret)&&p.username.equals(q.username)&&p.password.equals(q.password))return q;} proxyList.add(p); return p; } public static class ProxyInfo { public String address,username,password,secret,displayName; public int port; public boolean builtin; public ProxyInfo(String a,int p,String u,String w,String s){this(a,p,u,w,s,"");} public ProxyInfo(String a,int p,String u,String w,String s,String n){address=a;port=p;username=u;password=w;secret=s;displayName=n;} } }